<script lang="ts">
  import { onMount } from 'svelte';
  import { invoke } from '@tauri-apps/api/core';
  import ColorEditor from './ThemeColor.svelte';
  import { copy } from './input-preferences';
  import { switchPaint } from './theme-editor';
  import type { ThemeDocument,EditorDocument,Projection,RuntimeStatus,SurfaceName,Interaction,Paint } from './theme-editor';
  let draft=$state<ThemeDocument|null>(null),saved=$state<ThemeDocument|null>(null),source=$state<EditorDocument['source']>(null),projection=$state<Projection|null>(null);
  let runtime=$state<RuntimeStatus|null>(null),runtimeError=$state(''),error=$state(''),message=$state(''),validation=$state('');
  let busy=$state(false),validating=$state(false),loading=$state(true),tab=$state('paint'),sourceText=$state('');
  let surface=$state<SurfaceName>('bar'),interaction=$state<Interaction>('normal'),overwrite=$state(false);
  let pending=$state<'new'|'open'|null>(null),sourcePending=$state(false);
  let dirty=$derived(!!draft&&!!saved&&JSON.stringify(draft)!==JSON.stringify(saved));
  let packageOpen=$derived(!!source?.path.endsWith('.fdtheme'));
  let style=$derived(draft?.semantic.surfaces[surface]);
  let color=$derived(style?.[interaction]);
  let token:number|null=null,alive=true,projectSequence=0,savedToml='';
  const surfaces:SurfaceName[]=['bar','dock','button','active_button','popup','window_frame'];
  const interactions:Interaction[]=['normal','hover','pressed','selected','focused','urgent','disabled'];
  const edgeNumbers=[['border_width','Border width',0,16,.25],['radius','Corner radius',0,64,1],['shadow','Shadow',0,1,.05],['glow','Glow',0,1,.05]] as const;
  const typeNumbers=[['font_weight','Font weight',100,900,100],['size','Text size',8,72,1],['letter_spacing','Letter spacing',-10,30,.1]] as const;
  const layoutNumbers=[['bar_height','Bar height',0,512,1],['dock_width','Dock width',0,512,1],['padding','Padding',0,512,1],['gap','Gap',0,512,1],['icon_size','Icon size',0,512,1]] as const;
  function accept(next:EditorDocument){draft=copy(next.document);saved=copy(next.document);source=next.source;sourceText=next.toml;savedToml=next.toml;projection=next.preview;sourcePending=false;validation='';}
  $effect(()=>{if(!draft)return;const document=copy(draft);const sequence=++projectSequence;validating=true;const timer=window.setTimeout(()=>{void invoke<Projection>('project_theme',{document}).then(next=>{if(alive&&sequence===projectSequence){projection=next;validation='';}}).catch(cause=>{if(alive&&sequence===projectSequence)validation=String(cause);}).finally(()=>{if(alive&&sequence===projectSequence)validating=false;});},180);return()=>window.clearTimeout(timer);});
  async function openEditor(){try{const next=await invoke<{token:number;editor:EditorDocument;runtime:RuntimeStatus|null;runtime_error:string|null}>('open_theme_editor');token=next.token;if(!alive){await invoke('close_theme_editor',{token});return;}accept(next.editor);runtime=next.runtime;runtimeError=next.runtime_error??'';}catch(cause){if(alive)error=String(cause);}finally{if(alive)loading=false;}}
  async function file(type:'new'|'open'|'save'|'export'|'install',force=false){
    if(busy)return;if((type==='new'||type==='open')&&(dirty||sourcePending)&&!force){pending=type;return;}
    pending=null;busy=true;error='';message='';
    try{
      if(type==='new'){accept(await invoke<EditorDocument>('theme_editor_file',{action:{type:'new'}}));return;}
      if(type==='install'){if(!source)return;accept(await invoke<EditorDocument>('theme_editor_file',{action:{type:'install',path:source.path,expected_hash:source.hash,overwrite}}));message='Package installed. Select it in Appearance to keep it across sessions.';return;}
      let chosen:{path:string|null;hash:string|null}|null=null;
      if(type==='save')chosen=source&&!packageOpen?source:{path:null,hash:null};
      else chosen=await invoke('choose_theme_file',{kind:type==='open'?'open':type==='export'?'export':'save'});
      if(!chosen)return;
      const next=await invoke<EditorDocument>('theme_editor_file',{action:type==='open'?{type:'open',path:chosen.path}:{type,path:chosen.path,expected_hash:chosen.hash,document:copy(draft)}});
      if(type==='export')message='Theme package exported.';else {accept(next);message=type==='open'?'Theme opened.':'Theme saved.';}
    }catch(cause){error=String(cause);}finally{if(alive)busy=false;}
  }
  async function saveAs(){if(!draft||busy)return;busy=true;error='';try{const chosen=await invoke<{path:string;hash:string|null}|null>('choose_theme_file',{kind:'save'});if(chosen){accept(await invoke<EditorDocument>('theme_editor_file',{action:{type:'save',path:chosen.path,expected_hash:chosen.hash,document:copy(draft)}}));message='Theme saved.';}}catch(cause){error=String(cause);}finally{busy=false;}}
  async function loadSource(){busy=true;error='';try{const next=await invoke<EditorDocument>('theme_editor_file',{action:{type:'parse',source:sourceText}});draft=next.document;projection=next.preview;sourceText=next.toml;sourcePending=false;message='TOML loaded into your draft.';}catch(cause){error=String(cause);}finally{busy=false;}}
  async function session(command:'status'|'preview'|'apply'|'revert'){
    if(token===null||busy)return;busy=true;error='';message='';
    try{runtime=await invoke<RuntimeStatus>('theme_editor_runtime',{token,command,document:copy(draft),expectedRevision:runtime?.applied_revision??null});runtimeError='';message=command==='preview'?'Desktop preview started for 30 seconds.':command==='apply'?'Applied to this session. Save and install the theme to keep it across sessions.':command==='revert'?'Desktop preview reverted.':'Runtime status refreshed.';}catch(cause){runtimeError=String(cause);}finally{busy=false;}
  }
  async function wallpaper(){try{const chosen=await invoke<{path:string}|null>('choose_theme_file',{kind:'wallpaper'});if(chosen&&draft)draft.wallpaper.path=chosen.path;}catch(cause){error=String(cause);}}
  function mode(next:Paint['mode']){if(draft)draft.paint=switchPaint(draft.paint,next);}
  function addStop(){if(draft&&draft.paint.mode!=='solid'&&draft.paint.stops.length<8){draft.paint.stops.push({position:.5,color:copy(draft.paint.stops[0].color)});draft.paint.stops.sort((a,b)=>a.position-b.position);}}
  async function generateSource(){busy=true;try{const next=await invoke<EditorDocument>('theme_editor_file',{action:{type:'describe',document:copy(draft)}});sourceText=next.toml;sourcePending=false;}catch(cause){error=String(cause);}finally{busy=false;}}
  function discard(){if(saved)draft=copy(saved);sourceText=savedToml;error='';message='';sourcePending=false;}
  onMount(()=>{void openEditor();const timer=window.setInterval(()=>{if(token!==null&&runtime?.preview_active&&!busy)void invoke<RuntimeStatus>('theme_editor_runtime',{token,command:'status',document:null,expectedRevision:null}).then(next=>{if(alive)runtime=next;}).catch(()=>{});},1500);return()=>{alive=false;projectSequence++;window.clearInterval(timer);if(token!==null)void invoke('close_theme_editor',{token}).catch(()=>{});};});
</script>

<div class="page-heading"><div><div class="eyebrow">MAKE IT YOUR OWN</div><h1>Theme Editor</h1><p>Shape your desktop’s colors, surfaces, and details.</p></div></div>
{#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if validation}<div class="notice error" role="alert">{validation}</div>{/if}{#if message}<div class="notice success" role="status">{message}</div>{/if}
{#if runtimeError}<div class="notice runtime-notice" role="status">Desktop preview unavailable: {runtimeError} <button class="quiet" disabled={busy} onclick={()=>session('status')}>Retry connection</button></div>{/if}
{#if pending}<section class="editor-confirm" role="group" aria-label="Discard theme changes"><p>Your draft has unsaved changes. Continue without saving?</p><button class="quiet" onclick={()=>pending=null}>Keep editing</button><button class="quiet" onclick={()=>{if(pending)void file(pending,true);}}>Discard and continue</button></section>{/if}
{#if loading}<div class="loading" role="status">Opening theme editor…</div>{:else if draft}
<section class="settings-card"><div class="setting-row"><div><label for="theme-name">Theme name</label><p>{source?.path??'New theme · not saved yet'}</p></div><input id="theme-name" maxlength="200" type="text" bind:value={draft.name} disabled={busy} /></div><div class="file-actions"><button class="quiet" disabled={busy} onclick={()=>file('new')}>New theme</button><button class="quiet" disabled={busy} onclick={()=>file('open')}>Open…</button><button class="quiet" disabled={busy||validating||!!validation||packageOpen} onclick={()=>file('save')}>Save</button><button class="quiet" disabled={busy||validating||!!validation||packageOpen} onclick={saveAs}>Save As…</button><button class="quiet" disabled={busy||validating||!!validation||packageOpen} onclick={()=>file('export')}>Export package…</button><button class="quiet" disabled={!dirty||busy} onclick={discard}>Discard draft</button></div></section>
{#if packageOpen}<section class="editor-confirm"><h2>Theme package</h2><p>Install this package to unpack its wallpaper and add it to Appearance. Installation does not activate it.</p><label><input type="checkbox" bind:checked={overwrite} /> Replace an installed package with the same name</label><button class="quiet" disabled={busy} onclick={()=>file('install')}>Install package</button></section>{/if}
{#if projection}<section class="theme-illustration" style:background={projection.paint} aria-label="Local SDR theme illustration">{#if projection.wallpaper}<div class="wallpaper-preview" style:background-image={`url("${projection.wallpaper}")`} style:background-size={({fill:'cover',fit:'contain',stretch:'100% 100%',center:'auto',tile:'auto'} as const)[draft.wallpaper.fit]} style:background-repeat={draft.wallpaper.fit==='tile'?'repeat':'no-repeat'} style:filter={`blur(${draft.semantic.wallpaper.blur}px) saturate(${draft.semantic.wallpaper.saturation})`}></div>{#if projection.wallpaper_tint}<div class="wallpaper-overlay" style:background={projection.wallpaper_tint} style:mix-blend-mode="multiply"></div>{/if}<div class="wallpaper-overlay" style:background={`rgb(0 0 0 / ${draft.wallpaper.dim})`}></div>{/if}<div class="sample-theme" style:background={projection.surface} style:color={projection.text}><div class="sample-toolbar">{draft.name}</div><h2>Your space to create</h2><p>A local SDR illustration of your draft.</p><button style:background={projection.accent} tabindex="-1">Accent</button></div></section>{/if}
<div class="editor-tabs" role="group" aria-label="Theme editor sections">{#each [['paint','Paint'],['surfaces','Surfaces'],['layout','Layout & type'],['wallpaper','Wallpaper'],['source','TOML']] as [id,label]}<button class:active={tab===id} aria-pressed={tab===id} onclick={()=>tab=id}>{label}</button>{/each}</div>
<fieldset disabled={busy} class="editor-fields"><legend class="sr-only">Theme document</legend>
{#if tab==='paint'}
  <section class="section"><h2>Paint and dynamic range</h2><div class="settings-card"><div class="setting-row"><label for="theme-paint-mode">Paint</label><select id="theme-paint-mode" value={draft.paint.mode} onchange={event=>mode(event.currentTarget.value as Paint['mode'])}><option value="solid">Solid</option><option value="linear_gradient">Linear gradient</option><option value="radial_gradient">Radial gradient</option></select></div><div class="setting-row"><label for="theme-range">Dynamic range</label><select id="theme-range" bind:value={draft.dynamic_range}><option value="sdr">SDR</option><option value="hdr">HDR</option></select></div><div class="setting-row"><label for="theme-luminance">HDR luminance</label><input id="theme-luminance" type="number" min="203" max="1000" step="1" bind:value={draft.hdr_luminance_nits} /></div></div>
  {#if draft.paint.mode==='solid'}<ColorEditor label="Solid paint" bind:value={draft.paint.color} />{:else}
    <div class="settings-card">{#if draft.paint.mode==='linear_gradient'}<div class="setting-row"><label for="theme-angle">Gradient angle</label><input id="theme-angle" type="number" step="1" bind:value={draft.paint.angle} /></div>{:else}<div class="setting-row"><label for="theme-center-x">Radial center X</label><input id="theme-center-x" type="number" min="0" max="1" step=".01" bind:value={draft.paint.center[0]} /></div><div class="setting-row"><label for="theme-center-y">Radial center Y</label><input id="theme-center-y" type="number" min="0" max="1" step=".01" bind:value={draft.paint.center[1]} /></div><div class="setting-row"><label for="theme-radius">Radial radius</label><input id="theme-radius" type="number" min=".01" max="2" step=".01" bind:value={draft.paint.radius} /></div>{/if}<div class="setting-row"><label for="theme-interpolation">Interpolation gamut</label><select id="theme-interpolation" bind:value={draft.paint.interpolation.space}><option value="srgb">Linear sRGB</option><option value="display_p3">Linear Display P3</option><option value="rec2020">Linear Rec.2020</option></select></div><div class="setting-row"><label for="theme-premultiplied">Premultiplied alpha</label><input id="theme-premultiplied" class="switch" type="checkbox" role="switch" bind:checked={draft.paint.interpolation.premultiplied_alpha} /></div></div>
    {#each draft.paint.stops as stop,index}<div class="stop"><div class="stop-heading"><label for={`stop-position-${index}`}>Stop {index+1} position</label><input id={`stop-position-${index}`} type="number" min="0" max="1" step=".01" bind:value={stop.position} /><button class="quiet" disabled={draft.paint.stops.length<=2} onclick={()=>{if(draft&&draft.paint.mode!=='solid')draft.paint.stops.splice(index,1);}}>Remove stop {index+1}</button></div><ColorEditor label={`Stop ${index+1}`} bind:value={stop.color} /></div>{/each}<div class="file-actions"><button class="quiet" disabled={draft.paint.stops.length>=8} onclick={addStop}>Add gradient stop</button><button class="quiet" onclick={()=>{if(draft&&draft.paint.mode!=='solid')draft.paint.stops.sort((a,b)=>a.position-b.position);}}>Sort stops by position</button></div>
  {/if}</section>
{:else if tab==='surfaces'}
  <section class="section"><h2>Surface states</h2><div class="settings-card"><div class="setting-row"><label for="theme-surface">Surface</label><select id="theme-surface" bind:value={surface}>{#each surfaces as value}<option {value}>{value.replaceAll('_',' ')}</option>{/each}</select></div><div class="setting-row"><label for="theme-state">Interaction state</label><select id="theme-state" bind:value={interaction}>{#each interactions as value}<option {value}>{value}</option>{/each}</select></div>{#if interaction!=='normal'}<div class="setting-row"><label for="theme-inherit">Inherit normal color</label><input id="theme-inherit" type="checkbox" checked={!color} onchange={event=>{if(style&&interaction!=='normal')style[interaction]=event.currentTarget.checked?null:copy(style.normal);}} /></div>{/if}</div>{#if color&&style}<ColorEditor label={`${surface} ${interaction}`} bind:value={()=>style![interaction]!,value=>{if(style)style[interaction]=value;}} />{/if}</section>
  <section class="section"><h2>Edges</h2><ColorEditor label="Border color" bind:value={draft.semantic.edges.border_color} /><ColorEditor label="Inner highlight" bind:value={draft.semantic.edges.inner_highlight} /><div class="settings-card">{#each edgeNumbers as [key,label,min,max,step]}<div class="setting-row"><label for={`edge-${key}`}>{label}</label><input id={`edge-${key}`} type="number" {min} {max} {step} bind:value={draft.semantic.edges[key]} /></div>{/each}</div></section>
{:else if tab==='layout'}
  <section class="section"><h2>Typography</h2><ColorEditor label="Primary text" bind:value={draft.semantic.typography.primary} /><ColorEditor label="Secondary text" bind:value={draft.semantic.typography.secondary} /><div class="settings-card">{#each typeNumbers as [key,label,min,max,step]}<div class="setting-row"><label for={`type-${key}`}>{label}</label><input id={`type-${key}`} type="number" {min} {max} {step} bind:value={draft.semantic.typography[key]} /></div>{/each}</div></section>
  <section class="section"><h2>Layout</h2><div class="settings-card">{#each layoutNumbers as [key,label,min,max,step]}<div class="setting-row"><label for={`layout-${key}`}>{label}</label><input id={`layout-${key}`} type="number" {min} {max} {step} bind:value={draft.semantic.layout[key]} /></div>{/each}</div></section>
  <section class="section"><h2>Output color behavior</h2><div class="settings-card"><div class="setting-row"><label for="behavior-gamut">Gamut</label><select id="behavior-gamut" bind:value={draft.semantic.color_behavior.gamut}><option value="srgb">sRGB</option><option value="display_p3">Display P3</option><option value="rec2020">Rec.2020</option></select></div><div class="setting-row"><label for="behavior-range">Dynamic range</label><select id="behavior-range" bind:value={draft.semantic.color_behavior.dynamic_range}><option value="sdr">SDR</option><option value="hdr">HDR</option></select></div><div class="setting-row"><label for="behavior-white">SDR white (nits)</label><input id="behavior-white" type="number" min="80" max="400" bind:value={draft.semantic.color_behavior.sdr_white_nits} /></div><div class="setting-row"><label for="behavior-cap">Luminance cap (nits)</label><input id="behavior-cap" type="number" min="80" bind:value={draft.semantic.color_behavior.luminance_cap_nits} /></div><div class="setting-row"><label for="behavior-mapping">Gamut mapping</label><select id="behavior-mapping" bind:value={draft.semantic.color_behavior.gamut_mapping}><option value="clip">Clip</option><option value="perceptual">Perceptual</option><option value="preserve_hue">Preserve hue</option></select></div></div></section>
{:else if tab==='wallpaper'}
  <section class="section"><h2>Wallpaper</h2><div class="settings-card"><div class="setting-row"><div><strong>Image</strong><p>{draft.wallpaper.path??'No wallpaper selected'}</p></div><button class="quiet" onclick={wallpaper}>Choose wallpaper…</button><button class="quiet" disabled={!draft.wallpaper.path} onclick={()=>{if(draft)draft.wallpaper.path=null;}}>Remove wallpaper</button></div><div class="setting-row"><label for="wallpaper-fit">Fit</label><select id="wallpaper-fit" bind:value={draft.wallpaper.fit}>{#each ['fill','fit','stretch','center','tile'] as value}<option {value}>{value}</option>{/each}</select></div><div class="setting-row"><label for="wallpaper-dim">Dim</label><input id="wallpaper-dim" type="number" min="0" max="1" step=".05" bind:value={draft.wallpaper.dim} /></div><div class="setting-row"><label for="wallpaper-tint">Use tint</label><input id="wallpaper-tint" type="checkbox" checked={!!draft.wallpaper.tint} onchange={event=>{if(draft)draft.wallpaper.tint=event.currentTarget.checked?{space:'srgb',r:1,g:1,b:1,a:1}:null;}} /></div></div>{#if draft.wallpaper.tint}<ColorEditor label="Wallpaper tint" bind:value={draft.wallpaper.tint} />{/if}
  <div class="settings-card">{#each [['blur','Blur',0,64,1],['saturation','Saturation',0,2,.05]] as [key,label,min,max,step]}<div class="setting-row"><label for={`wallpaper-${key}`}>{label}</label><input id={`wallpaper-${key}`} type="number" min={Number(min)} max={Number(max)} step={Number(step)} bind:value={draft.semantic.wallpaper[key as 'blur'|'saturation']} /></div>{/each}<div class="setting-row"><label for="wallpaper-accent">Automatic wallpaper accent</label><input id="wallpaper-accent" class="switch" type="checkbox" role="switch" bind:checked={draft.semantic.wallpaper.automatic_accent} /></div>{#each ['rail_opacity','dock_opacity'] as key}<div class="setting-row"><label for={key}>{key.replaceAll('_',' ')}</label><input id={key} type="number" min="0" max="1" step=".05" bind:value={draft.backing[key as 'rail_opacity'|'dock_opacity']} /></div>{/each}</div></section>
{:else}
  <section class="section"><h2>Portable TOML document</h2><p class="description">Paste a document and load it into your draft. Generate TOML to refresh this source from the controls.</p><label for="theme-source" class="sr-only">Theme TOML source</label><textarea id="theme-source" rows="18" spellcheck="false" bind:value={sourceText} oninput={()=>sourcePending=true}></textarea><div class="file-actions"><button class="quiet" disabled={busy||!sourcePending} onclick={loadSource}>Load TOML into draft</button><button class="quiet" disabled={busy||validating||!!validation} onclick={generateSource}>Generate TOML from draft</button></div></section>
{/if}

<style>
  .file-actions{display:flex;gap:8px;flex-wrap:wrap;padding:16px 18px}.editor-tabs{display:flex;gap:5px;flex-wrap:wrap;background:var(--fd-surface-muted);border:1px solid var(--fd-border);border-radius:10px;padding:5px;margin:25px 0}.editor-tabs button{padding:10px 14px;border-radius:7px;background:transparent;font-size:12px;color:var(--fd-text-muted)}.editor-tabs button.active{background:var(--fd-surface);color:var(--fd-accent)}.editor-fields{border:0;padding:0;margin:0;min-width:0}input,select{padding:9px 11px;border:1px solid var(--fd-border);border-radius:8px;background:var(--fd-surface);color:var(--fd-text);font:inherit;font-size:12px}input[type=number]{width:100px}input[type=text]{max-width:250px;width:45%}.setting-row>div{min-width:0}.setting-row p{overflow-wrap:anywhere}.wallpaper-preview,.wallpaper-overlay{position:absolute;inset:0;pointer-events:none}.wallpaper-preview{background-position:center}.theme-illustration{position:relative;isolation:isolate;height:240px;border:1px solid var(--fd-border);border-radius:var(--fd-radius);margin-top:24px;display:grid;place-items:center;overflow:hidden}.sample-theme{position:relative;border:1px solid #ffffff55;border-radius:12px;box-shadow:0 15px 40px #0003;min-width:250px;text-align:center;padding-bottom:22px}.sample-toolbar{padding:12px;font-size:11px;border-bottom:1px solid #8885;margin-bottom:20px}.sample-theme h2{font-size:18px}.sample-theme p{font-size:11px;margin:12px}.sample-theme button{color:white;border-radius:6px;padding:8px 14px;font-size:11px;pointer-events:none}.description,.editor-confirm p{font-size:12px;line-height:1.8;color:var(--fd-text-muted);margin:12px 0 16px}.editor-confirm{border:1px solid var(--fd-border);border-radius:var(--fd-radius);background:var(--fd-surface);padding:20px;margin:18px 0}.editor-confirm button{margin:8px}.editor-confirm label{display:block;font-size:12px}.stop{margin:20px 0}.stop-heading{display:flex;gap:12px;align-items:center;flex-wrap:wrap;font-size:12px}.stop-heading .quiet{margin-left:auto}.runtime-card{border-top:1px solid var(--fd-border);padding-top:25px}.runtime-card .file-actions{padding-left:0}.runtime-notice{background:var(--fd-accent-soft);color:var(--fd-text-muted);font-size:12px;line-height:1.8;overflow-wrap:anywhere}.contrast ul{font-size:11px;line-height:1.9;color:var(--fd-text-muted);padding-left:20px}textarea{display:block;width:100%;padding:15px;border:1px solid var(--fd-border);border-radius:10px;background:var(--fd-surface);color:var(--fd-text);font:11px/1.7 ui-monospace,monospace;resize:vertical}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.footnote{line-height:1.8}@media(max-width:600px){.editor-tabs button{padding:8px;font-size:10px}.setting-row input[type=text]{width:100%;max-width:none}}
</style>
</fieldset>
{#if projection?.contrast.length}<section class="section contrast"><h2>Contrast checks</h2><p class="description">{projection.contrast.length} surface/state combinations are below the recommended text contrast.</p><ul>{#each projection.contrast.slice(0,12) as issue}<li>{issue.surface} · {issue.state}: {issue.ratio.toFixed(2)}:1 (recommended {issue.required}:1)</li>{/each}</ul></section>{/if}
<section class="section runtime-card"><h2>Desktop preview</h2><p class="description">Local colors above are an SDR illustration. Desktop previews last 30 seconds and revert automatically. Applying changes this session; saving a file is separate.</p><div class="file-actions"><button class="quiet" disabled={busy||validating||!!validation||!runtime||packageOpen} onclick={()=>session('preview')}>Preview on desktop</button><button class="quiet" disabled={busy||!runtime?.preview_active} onclick={()=>session('revert')}>Revert desktop preview</button><button class="quiet" disabled={busy||validating||!!validation||!runtime||packageOpen} onclick={()=>session('apply')}>Apply to this session</button><button class="quiet" disabled={busy} onclick={()=>session('status')}>Refresh runtime status</button></div>{#if runtime}<p class="footnote">{runtime.preview_active?'Desktop preview is active':'No desktop preview'} · Session revision {runtime.applied_revision}{!runtime.gradient_rendering||!runtime.semantic_rendering?' · The compositor supports only part of this theme.':''}</p>{/if}</section>
{/if}
